19	const defaultPageSize = 10
20	
21	// Chrome: filter bar (1) + separator (1) + list header (1) + separator (1) + status bar (1) + padding (1) = 6
22	const verticalChrome = 6
23	
24	// GenerateFunc generates summary and facets for a single session on demand.
25	type GenerateFunc func(ctx context.Context, row insightsdb.SessionRow) (insightsdb.SessionRow, error)
26	
27	type branchFilter int
28	
29	const (
30		filterRepo          branchFilter = iota // default branch (main/master)
31		filterCurrentBranch                     // current working branch
32		filterAllBranches                       // all branches
33	)
34	
35	type timeFilter int
36	
37	const (
38		timeFilter24h timeFilter = iota
39		timeFilter7d
40		timeFilter30d
41		timeFilterAll
42	)
