44	//nolint:recvcheck // bubbletea pattern: value receiver for interface, pointer receivers for mutation helpers
45	type rootModel struct {
46		ctx           context.Context
47		rows          []insightsdb.SessionRow
48		filteredRows  []insightsdb.SessionRow
49		currentBranch string
50		defaultBranch string
51		branchFilter  branchFilter
52		timeFilter    timeFilter
53		cursor        int
54		paginator     paginator.Model
55		pageSize      int
56		detailVP      viewport.Model
57		width         int
58		height        int
59		styles        styles
60		generateFn    GenerateFunc
61		generating    bool
62		genStatus     string // status message for generate operation
63		accessible    bool   // accessible mode fallback
64	}
65	
66	type generateDoneMsg struct {
67		row insightsdb.SessionRow
68	}
69	
70	type generateErrMsg struct {
71		err error
72	}
73	
74	func Run(ctx context.Context, rows []insightsdb.SessionRow) error {
75		return RunWithCurrentBranch(ctx, rows, "", "", nil)
76	}
77	
78	func RunWithCurrentBranch(_ context.Context, rows []insightsdb.SessionRow, currentBranch, defaultBranch string, generateFn GenerateFunc) error {
79		p := tea.NewProgram(newRootModel(rows, currentBranch, defaultBranch, generateFn), tea.WithAltScreen())
80		_, err := p.Run()
81		if err != nil {
82			return fmt.Errorf("run summary TUI: %w", err)
83		}
84		return nil
85	}
86	
87	func newRootModel(rows []insightsdb.SessionRow, currentBranch, defaultBranch string, generateFn GenerateFunc) rootModel {
88		s := newStyles()
89		p := paginator.New()
90		p.PerPage = defaultPageSize
91	
92		accessible := os.Getenv("ACCESSIBLE") != ""
93	
94		m := rootModel{
95			ctx:           context.Background(),
96			rows:          append([]insightsdb.SessionRow(nil), rows...),
97			currentBranch: currentBranch,
98			defaultBranch: defaultBranch,
99			branchFilter:  filterRepo,
100			timeFilter:    timeFilterAll,
101			paginator:     p,
102			pageSize:      defaultPageSize,
103			styles:        s,
104			width:         100,
105			height:        30,
106			generateFn:    generateFn,
107			accessible:    accessible,
108		}
109		m.rebuildFilteredRows()
110		m.updateDetailViewport()
111		return m
112	}
113	
114	func (m rootModel) Init() tea.Cmd {
115		return nil
116	}
117	
118	//nolint:cyclop,ireturn // required by bubbletea Model interface; state machine has inherent branching
119	func (m rootModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
120		switch msg := msg.(type) {
121		case tea.WindowSizeMsg:
122			m.resize(msg.Width, msg.Height)
123			return m, nil
124	
125		case tea.KeyMsg:
126			return m.updateKeys(msg)
127	
128		case generateDoneMsg:
129			m.generating = false
130			m.genStatus = "Generated"
131			m.updateRowData(msg.row)
132			m.updateDetailViewport()
133			return m, nil
134	
135		case generateErrMsg:
136			m.generating = false
137			m.genStatus = "Error: " + msg.err.Error()
138			return m, nil
139		}
140	
141		return m, nil
142	}
143	
144	//nolint:cyclop,ireturn // required by bubbletea pattern
145	func (m rootModel) updateKeys(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
146		switch {
147		case key.Matches(msg, keys.quit):
148			return m, tea.Quit
149		case key.Matches(msg, keys.cycleTimeFilter):
150			m.cycleTime()
151			return m, nil
152		case key.Matches(msg, keys.cycleBranchFilter):
153			m.cycleBranch()
154			return m, nil
155		case key.Matches(msg, keys.cursorDown):
156			m.moveCursor(1)
157			return m, nil
158		case key.Matches(msg, keys.cursorUp):
159			m.moveCursor(-1)
160			return m, nil
161		case key.Matches(msg, keys.nextPage):
162			m.nextPage()
163			return m, nil
164		case key.Matches(msg, keys.prevPage):
165			m.prevPage()
166			return m, nil
167		case key.Matches(msg, keys.generate):
168			return m.handleGenerate()
169		}
170	
171		//nolint:exhaustive // only Ctrl+C needs special handling here
172		switch msg.Type {
173		case tea.KeyCtrlC:
174			return m, tea.Quit
175		default:
176		}
177	
178		// Scroll detail viewport
179		var cmd tea.Cmd
180		m.detailVP, cmd = m.detailVP.Update(msg)
181		return m, cmd
182	}
183	
184	//nolint:ireturn // required by bubbletea pattern
185	func (m rootModel) handleGenerate() (tea.Model, tea.Cmd) {
186		if m.generateFn == nil || m.generating {
187			return m, nil
188		}
189		row := m.selectedRow()
190		if row == nil {
191			return m, nil
192		}
193		m.generating = true
194		m.genStatus = "Generating..."
195		selected := *row
196		ctx := m.ctx
197		fn := m.generateFn
198		return m, func() tea.Msg {
199			updated, err := fn(ctx, selected)
200			if err != nil {
201				return generateErrMsg{err: err}
202			}
203			return generateDoneMsg{row: updated}
204		}
205	}
