207	func (m rootModel) View() string {
208		var b strings.Builder
209	
210		// Filter bar
211		b.WriteString(m.renderFilterBar())
212		b.WriteString("\n")
213	
214		listWidth := m.listWidth()
215		detailWidth := m.detailWidth()
216		contentHeight := m.contentHeight()
217	
218		// List pane
219		listPane := m.renderListPane(listWidth, contentHeight)
220	
221		// Detail pane
222		detailPane := m.renderDetailPane(detailWidth, contentHeight)
223	
224		// Join horizontally
225		split := lipgloss.JoinHorizontal(lipgloss.Top, listPane, detailPane)
226		b.WriteString(split)
227		b.WriteString("\n")
228	
229		// Status bar
230		b.WriteString(m.renderStatusBar())
231	
232		return b.String()
233	}
