237	func (m rootModel) renderFilterBar() string {
238		sep := m.styles.render(m.styles.filterSeparator, " │ ")
239	
240		// TIME filter
241		timeLabels := []struct {
242			filter timeFilter
243			label  string
244		}{
245			{timeFilter24h, "24h"},
246			{timeFilter7d, "7d"},
247			{timeFilter30d, "30d"},
248			{timeFilterAll, "all"},
249		}
250		var timeParts []string
251		for _, item := range timeLabels {
252			if item.filter == m.timeFilter {
253				timeParts = append(timeParts, m.styles.render(m.styles.filterActive, item.label))
254			} else {
255				timeParts = append(timeParts, m.styles.render(m.styles.filterInactive, item.label))
256			}
257		}
258		timeStr := m.styles.render(m.styles.filterLabel, "TIME: ") + strings.Join(timeParts, sep)
259	
260		// BRANCH filter
261		branchLabels := []struct {
262			filter branchFilter
263			label  string
264		}{
265			{filterRepo, "repo"},
266			{filterCurrentBranch, "current"},
267			{filterAllBranches, "all"},
268		}
269		var branchParts []string
270		for _, item := range branchLabels {
271			if item.filter == m.branchFilter {
272				branchParts = append(branchParts, m.styles.render(m.styles.filterActive, item.label))
273			} else {
274				branchParts = append(branchParts, m.styles.render(m.styles.filterInactive, item.label))
275			}
276		}
277		branchStr := m.styles.render(m.styles.filterLabel, "BRANCH: ") + strings.Join(branchParts, sep)
278	
279		count := m.styles.render(m.styles.sessionCount, fmt.Sprintf("%d sessions", len(m.filteredRows)))
280	
281		return timeStr + "    " + branchStr + "    " + count
282	}
