284	// --- List pane ---
285	
286	func (m rootModel) renderListPane(width, height int) string {
287		var b strings.Builder
288	
289		// Column header
290		header := m.formatListRow("TIME", "CKPT", "AGENT", width)
291		b.WriteString(m.styles.render(m.styles.listHeader, header))
292		b.WriteString("\n")
293		b.WriteString(strings.Repeat("─", width))
294		b.WriteString("\n")
295	
296		pageRows := m.currentPageRows()
297		listHeight := height - 2 // header + separator
298	
299		for i, row := range pageRows {
300			if i >= listHeight {
301				break
302			}
303			timeStr := row.CreatedAt.Format("01-02 15:04")
304			checkpoint := row.CheckpointID
305			if len(checkpoint) > 6 {
306				checkpoint = checkpoint[:6]
307			}
308			agent := truncate(row.Agent, 8)
309			line := m.formatListRow(timeStr, checkpoint, agent, width)
310	
311			if i == m.cursor {
312				// Selected: amber text + dark background + left accent
313				accent := m.styles.render(m.styles.listAccent, "▸ ")
314				styled := m.styles.render(m.styles.listSelected, line)
315				if m.styles.colorEnabled {
316					styled = m.styles.listSelectedBg.Render(styled)
317				}
318				b.WriteString(accent + styled)
319			} else {
320				b.WriteString("  " + m.styles.render(m.styles.listNormal, line))
321			}
322			b.WriteString("\n")
323		}
324	
325		// Fill remaining lines
326		for i := len(pageRows); i < listHeight; i++ {
327			b.WriteString("\n")
328		}
329	
330		// Page indicator
331		pageInfo := m.styles.render(m.styles.dim, fmt.Sprintf("%d/%d", m.paginator.Page+1, max(1, m.paginator.TotalPages)))
332		b.WriteString(m.styles.render(m.styles.dim, "←→ ") + pageInfo)
333	
334		return b.String()
335	}
