341	// --- Detail pane ---
342	
343	func (m rootModel) renderDetailPane(width, height int) string {
344		var b strings.Builder
345	
346		row := m.selectedRow()
347		if row == nil {
348			b.WriteString(m.styles.render(m.styles.emptyState, "  No sessions to display"))
349			return b.String()
350		}
351	
352		// Fixed metadata header
353		header := renderMetadataHeader(m.styles, *row, width)
354		b.WriteString(header)
355		b.WriteString("\n")
356	
357		// Scrollable viewport fills remaining space
358		headerLines := strings.Count(header, "\n") + 1
359		vpHeight := max(3, height-headerLines-1)
360		if m.detailVP.Height != vpHeight || m.detailVP.Width != width {
361			m.detailVP.Width = width
362			m.detailVP.Height = vpHeight
363		}
364		b.WriteString(m.detailVP.View())
365	
366		return b.String()
367	}
