369	func (m rootModel) renderStatusBar() string {
370		var parts []string
371		parts = append(parts, "j/k navigate")
372		parts = append(parts, "1 time")
373		parts = append(parts, "2 branch")
374		parts = append(parts, "←→ page")
375		if m.generateFn != nil {
376			parts = append(parts, "g generate")
377		}
378		parts = append(parts, "q quit")
379		status := strings.Join(parts, "  ")
380	
381		if m.genStatus != "" {
382			style := m.styles.filterActive
383			if strings.HasPrefix(m.genStatus, "Error:") {
384				style = m.styles.errorText
385			}
386			status = m.styles.render(style, m.genStatus) + "  " + status
387		}
388	
389		return m.styles.render(m.styles.statusBar, status)
390	}
