392	// --- Layout helpers ---
393	
394	func (m rootModel) listWidth() int {
395		return max(30, m.width*30/100)
396	}
397	
398	func (m rootModel) detailWidth() int {
399		return max(30, m.width-m.listWidth()-1)
400	}
401	
402	func (m rootModel) contentHeight() int {
403		return max(5, m.height-verticalChrome)
