406	// --- Data management ---
407	
408	func (m *rootModel) updateRowData(updated insightsdb.SessionRow) {
409		for i, row := range m.rows {
410			if row.SessionID == updated.SessionID {
411				m.rows[i] = updated
412				break
413			}
414		}
415		for i, row := range m.filteredRows {
416			if row.SessionID == updated.SessionID {
417				m.filteredRows[i] = updated
418				break
419			}
420		}
421	}
422	
423	func (m *rootModel) rebuildFilteredRows() {
424		m.filteredRows = m.applyFilter()
425		m.paginator.PerPage = m.pageSize
426		totalPages := m.paginator.SetTotalPages(len(m.filteredRows))
427		if totalPages == 0 {
428			m.paginator.TotalPages = 1
429		}
430		if m.paginator.Page >= m.paginator.TotalPages {
431			m.paginator.Page = max(0, m.paginator.TotalPages-1)
432		}
433		if m.paginator.Page < 0 {
434			m.paginator.Page = 0
435		}
436		if m.cursor >= len(m.currentPageRows()) {
437			m.cursor = max(0, len(m.currentPageRows())-1)
438		}
439	}
440	
441	func (m rootModel) applyFilter() []insightsdb.SessionRow {
442		filtered := make([]insightsdb.SessionRow, 0, len(m.rows))
443		now := time.Now()
444		for _, row := range m.rows {
445			// Time filter
446			switch m.timeFilter {
447			case timeFilter24h:
448				if now.Sub(row.CreatedAt) > 24*time.Hour {
449					continue
450				}
451			case timeFilter7d:
452				if now.Sub(row.CreatedAt) > 7*24*time.Hour {
453					continue
454				}
455			case timeFilter30d:
456				if now.Sub(row.CreatedAt) > 30*24*time.Hour {
457					continue
458				}
459			case timeFilterAll:
460				// no time filtering
461			}
462	
463			// Branch filter
464			if m.branchFilter == filterRepo && m.defaultBranch != "" && row.Branch != m.defaultBranch {
465				continue
466			}
467			if m.branchFilter == filterCurrentBranch && m.currentBranch != "" && row.Branch != m.currentBranch {
468				continue
469			}
470			filtered = append(filtered, row)
471		}
472		return filtered
473	}
474	
475	func (m rootModel) currentPageRows() []insightsdb.SessionRow {
476		if len(m.filteredRows) == 0 {
477			return nil
478		}
479		start, end := m.paginator.GetSliceBounds(len(m.filteredRows))
480		if start >= len(m.filteredRows) {
481			return nil
482		}
483		if end > len(m.filteredRows) {
484			end = len(m.filteredRows)
485		}
486		return m.filteredRows[start:end]
487	}
488	
489	func (m rootModel) selectedRow() *insightsdb.SessionRow {
490		rows := m.currentPageRows()
491		if m.cursor < 0 || m.cursor >= len(rows) {
492			return nil
493		}
494		return &rows[m.cursor]
495	}
496	
497	// --- Navigation ---
498	
499	func (m *rootModel) moveCursor(delta int) {
500		pageRows := m.currentPageRows()
501		if len(pageRows) == 0 {
502			return
503		}
504		m.cursor += delta
505		if m.cursor < 0 {
506			m.cursor = 0
507		}
508		if m.cursor >= len(pageRows) {
509			m.cursor = len(pageRows) - 1
510		}
511		m.genStatus = "" // clear status on navigation
512		m.updateDetailViewport()
513	}
514	
515	func (m *rootModel) cycleTime() {
516		m.timeFilter = (m.timeFilter + 1) % 4
517		m.paginator.Page = 0
518		m.cursor = 0
519		m.genStatus = ""
520		m.rebuildFilteredRows()
521		m.updateDetailViewport()
522	}
523	
524	func (m *rootModel) cycleBranch() {
525		m.branchFilter = (m.branchFilter + 1) % 3
526		m.paginator.Page = 0
527		m.cursor = 0
528		m.genStatus = ""
529		m.rebuildFilteredRows()
530		m.updateDetailViewport()
531	}
532	
533	func (m *rootModel) nextPage() {
534		if m.paginator.OnLastPage() {
535			return
536		}
537		m.paginator.NextPage()
538		m.cursor = 0
539		m.genStatus = ""
540		m.updateDetailViewport()
541	}
542	
543	func (m *rootModel) prevPage() {
544		if m.paginator.OnFirstPage() {
545			return
546		}
547		m.paginator.PrevPage()
548		m.cursor = 0
549		m.genStatus = ""
550		m.updateDetailViewport()
551	}
552	
553	func (m *rootModel) updateDetailViewport() {
554		row := m.selectedRow()
555		if row == nil {
556			m.detailVP.SetContent("")
557			return
558		}
559		content := renderDetailContent(m.styles, *row, m.detailWidth())
560		m.detailVP.SetContent(content)
561	}
562	
563	func (m *rootModel) resize(width, height int) {
564		selectedSessionID := ""
565		if selected := m.selectedRow(); selected != nil {
566			selectedSessionID = selected.SessionID
567		}
568	
569		m.width = width
570		m.height = height
571	
572		contentHeight := m.contentHeight()
573		listHeight := contentHeight - 2 // header + separator
574		m.pageSize = max(1, listHeight)
575	
576		m.detailVP = viewport.New(m.detailWidth(), max(3, contentHeight-4))
577	
578		m.rebuildFilteredRows()
579		m.restoreSelection(selectedSessionID)
580		m.updateDetailViewport()
581	}
582	
583	func (m *rootModel) restoreSelection(sessionID string) {
584		if sessionID == "" || len(m.filteredRows) == 0 {
585			return
586		}
587	
588		for idx, row := range m.filteredRows {
589			if row.SessionID != sessionID {
590				continue
591			}
592	
593			m.paginator.Page = idx / m.pageSize
594			cursor := idx % m.pageSize
595			pageRows := m.currentPageRows()
596			if len(pageRows) > 0 && cursor >= len(pageRows) {
597				cursor = len(pageRows) - 1
598			}
599			m.cursor = cursor
600			return
601		}
602	}
