12	// renderMetadataHeader renders the fixed metadata header with two side-by-side boxes.
13	func renderMetadataHeader(s styles, row insightsdb.SessionRow, width int) string {
14		tokensWidth := 14
15		sessionWidth := max(0, width-tokensWidth-3) // gap between boxes
16	
17		// SESSION box content
18		var parts []string
19		if row.Branch != "" {
20			parts = append(parts, s.render(s.detailLabel, "branch:")+s.render(s.detailValue, " "+row.Branch))
21		}
22		if row.Model != "" {
23			parts = append(parts, s.render(s.detailLabel, "model:")+s.render(s.detailValue, " "+row.Model))
24		}
25		parts = append(parts, s.render(s.detailLabel, "turns:")+s.render(s.detailValue, " "+strconv.Itoa(row.TurnCount)))
26	
27		sessionContent := strings.Join(parts, s.render(s.dim, " · "))
28		sessionBox := s.renderBox("SESSION", sessionContent, sessionWidth)
29	
30		// TOKENS box content
31		tokensContent := s.render(s.detailValue, formatTokensForDetail(row.TotalTokens))
32		tokensBox := s.renderBox("TOKENS", tokensContent, tokensWidth)
33	
34		return lipgloss.JoinHorizontal(lipgloss.Top, sessionBox, " ", tokensBox)
35	}
36	
37	// renderDetailContent renders the scrollable detail content with bordered boxes.
38	func renderDetailContent(s styles, row insightsdb.SessionRow, width int) string {
39		var sections []string
40	
41		// Summary section
42		if row.HasSummary {
43			sections = append(sections, renderSummaryBox(s, row, width))
44		}
45	
46		// Friction section
47		if row.HasSummary && len(row.Friction) > 0 {
48			sections = append(sections, renderFrictionBox(s, row, width))
49		}
50	
51		// Learnings section
52		if row.HasSummary && len(row.Learnings) > 0 {
53			sections = append(sections, renderLearningsBox(s, row, width))
54		}
55	
56		// Insights section (merged facets)
57		if row.HasFacets {
58			if box := renderInsightsBox(s, row, width); box != "" {
59				sections = append(sections, box)
60			}
61		}
62	
63		if len(sections) == 0 {
64			return s.render(s.emptyState, "  No summary or insights cached. Press g to generate.")
65		}
66	
67		return strings.Join(sections, "\n")
68	}
69	
70	func renderSummaryBox(s styles, row insightsdb.SessionRow, width int) string {
71		var lines []string
72		if row.Intent != "" {
73			lines = append(lines, s.render(s.detailLabel, "Intent: ")+s.render(s.detailValue, row.Intent))
74		}
75		if row.Outcome != "" {
76			lines = append(lines, s.render(s.detailLabel, "Outcome: ")+s.render(s.detailValue, row.Outcome))
77		}
78		if len(lines) == 0 {
79			return ""
80		}
81		return s.renderBox("SUMMARY", strings.Join(lines, "\n"), width)
82	}
83	
84	func renderFrictionBox(s styles, row insightsdb.SessionRow, width int) string {
