126	func loadSummarySessions(ctx context.Context, opts summaryOptions) ([]insightsdb.SessionRow, error) {
127		worktreeRoot, err := paths.WorktreeRoot(ctx)
128		if err != nil {
129			return nil, fmt.Errorf("not in a git repository: %w", err)
130		}
131	
132		idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
133		if err != nil {
134			return nil, fmt.Errorf("open insights cache: %w", err)
135		}
136		defer func() { _ = idb.Close() }()
137	
138		outputLimit := normalizedSummarySessionLimit(opts.Last)
139	
140		rows, err := idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
141		if err != nil {
142			return nil, fmt.Errorf("query sessions: %w", err)
143		}
144		if len(rows) == 0 {
145			// First-run fallback: populate the cache if we have nothing local yet.
146			if err := summaryRefreshCacheIfStale(ctx, idb); err != nil {
147				return nil, fmt.Errorf("refresh insights cache: %w", err)
148			}
149			rows, err = idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
150			if err != nil {
151				return nil, fmt.Errorf("query sessions after refresh: %w", err)
152			}
153		}
154	
155		summaryBackfillSummaries(ctx, io.Discard, idb, outputLimit, false, "")
156		summaryBackfillFacets(ctx, io.Discard, idb, outputLimit, false, "")
157	
158		rows, err = idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
159		if err != nil {
160			return nil, fmt.Errorf("query sessions after backfill: %w", err)
161		}
162	
163		ownerID := ""
164		if opts.Me {
165			ownerID, err = githubidentity.ResolveUsername(ctx)
166			if err != nil {
167				return nil, fmt.Errorf("resolve github username: %w", err)
168			}
169		}
170	
171		hasCLIFilters := opts.Agent != "" || opts.Branch != "" || ownerID != ""
172	
173		filtered := make([]insightsdb.SessionRow, 0, len(rows))
174		for _, row := range rows {
175			if opts.Agent != "" && !strings.EqualFold(strings.TrimSpace(row.Agent), strings.TrimSpace(opts.Agent)) {
176				continue
177			}
178			if opts.Branch != "" && !strings.EqualFold(strings.TrimSpace(row.Branch), strings.TrimSpace(opts.Branch)) {
179				continue
180			}
181			if ownerID != "" && !strings.EqualFold(strings.TrimSpace(row.OwnerID), ownerID) {
182				continue
183			}
184			filtered = append(filtered, row)
185			// Only cap results when CLI filters or JSON output are in use.
186			// The TUI has its own branch filter, so it needs the full result set.
187			if hasCLIFilters && len(filtered) == outputLimit {
188				break
189			}
190		}
191	
192		return filtered, nil
193	}
