62	// QueryRecurringFriction returns friction themes occurring at least minCount times,
63	// ordered by count descending.
64	func (idb *InsightsDB) QueryRecurringFriction(ctx context.Context, minCount int) ([]FrictionTheme, error) {
65		rows, err := idb.db.QueryContext(ctx, `
66			SELECT text, COUNT(*) AS cnt, GROUP_CONCAT(DISTINCT checkpoint_id) AS sessions
67			FROM friction
68			GROUP BY text
69			HAVING cnt >= ?
70			ORDER BY cnt DESC
71		`, minCount)
72		if err != nil {
73			return nil, fmt.Errorf("query recurring friction: %w", err)
74		}
75		defer rows.Close()
76	
77		var themes []FrictionTheme
78		for rows.Next() {
79			var theme FrictionTheme
